const publicStyle = '''
:root{color-scheme:dark;--bg:#090e1a;--surface:#11192a;--line:#26304a;--text:#edf1ff;--muted:#a5b0ca;--accent:#a59aff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif;line-height:1.65}a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #b7a5ff;outline-offset:5px}header{border-bottom:1px solid var(--line);background:#0d1320}nav{max-width:1240px;margin:auto;min-height:88px;display:flex;align-items:center;gap:34px;padding:20px 32px}.brand{display:flex;align-items:center;gap:12px;letter-spacing:3px;font-weight:800;font-size:21px}.mark{color:#b5a6ff;font-size:30px;line-height:1}.nav-links{display:flex;align-items:center;gap:26px;margin-left:auto}.nav-links a{font-size:14px;color:var(--muted)}.button{display:inline-flex;justify-content:center;align-items:center;gap:8px;border:1px solid #7164d9;border-radius:9px;background:#7c6bea;color:white;padding:11px 20px;font:inherit;font-size:14px;font-weight:600;cursor:pointer}.button:hover{background:#9383f6;color:white}.button.secondary{background:transparent;border-color:var(--line);color:var(--text)}.nav-links .button{color:white}main{max-width:1240px;margin:auto;padding:48px 32px 80px}.eyebrow{font-size:12px;letter-spacing:2.5px;text-transform:uppercase;color:var(--accent);font-weight:700}.hero{padding:35px 0 58px;max-width:850px}.hero h1{font-size:clamp(40px,6vw,72px);line-height:1.1;letter-spacing:-2.5px;margin:18px 0 24px;font-weight:750}.hero h1 em{font-style:normal;color:#ad9fff}.hero p{color:var(--muted);font-size:18px;max-width:650px}.hero .actions{margin-top:30px}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.section-title{display:flex;align-items:baseline;justify-content:space-between;gap:20px;margin:22px 0}.section-title h1,.section-title h2{margin:0;line-height:1.3;font-size:27px;letter-spacing:-.5px}.section-title small{color:var(--muted)}.filters{padding:18px;border:1px solid var(--line);border-radius:12px;display:flex;gap:14px;align-items:end;background:#101727;margin:22px 0 28px}.field{display:flex;flex-direction:column;gap:6px;flex:1}.field label{color:var(--muted);font-size:12px}input,select{border:1px solid #303c56;background:#0c1322;color:var(--text);padding:12px 14px;border-radius:8px;font:inherit;width:100%;min-width:0}input::placeholder{color:#7a87a2}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.card{border:1px solid var(--line);background:var(--surface);border-radius:13px;overflow:hidden;transition:border-color .2s,transform .2s}.card:hover{border-color:#7164bb;transform:translateY(-3px)}.preview{height:240px;background:radial-gradient(ellipse at 50% 55%,#26314e,#121b2d);display:flex;align-items:center;justify-content:center;overflow:hidden}.preview img{width:100%;height:100%;object-fit:contain}.card-body{padding:19px 20px 20px}.card h3{font-size:17px;margin:8px 0 5px;letter-spacing:-.2px}.card p{font-size:13px;color:var(--muted);margin:0}.tag-row{display:flex;justify-content:space-between;align-items:center;gap:8px}.tag{font-size:10px;letter-spacing:1px;text-transform:uppercase;color:#b7acf8;background:#7761cb22;border:1px solid #7164b84a;border-radius:5px;padding:3px 7px}.format{font-size:11px;color:#93a2be}.categories{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.category{font-size:13px;border:1px solid var(--line);border-radius:20px;padding:7px 16px;color:var(--muted)}.category:hover,.category.active{border-color:#8f7cdb;color:var(--accent);background:#7761cb18}.notice{padding:42px 32px;border:1px solid var(--line);border-radius:14px;background:#11192a;text-align:center;margin:25px 0}.notice h2{font-size:22px;margin:0 0 10px}.notice p{color:var(--muted);max-width:600px;margin:0 auto 20px}.muted{color:var(--muted)}.breadcrumb{color:var(--muted);font-size:13px;margin-bottom:28px}.detail{display:grid;grid-template-columns:1.25fr 1fr;gap:36px}.detail .preview{height:480px;border:1px solid var(--line);border-radius:14px}.detail h1{font-size:37px;line-height:1.2;letter-spacing:-1px;margin:14px 0}.detail .description{white-space:pre-wrap;color:var(--muted)}.details-list{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line);margin:28px 0}.details-list dt,.details-list dd{padding:13px 0;margin:0;border-bottom:1px solid var(--line);font-size:14px}.details-list dt{color:var(--muted)}.details-list dd{text-align:right}.detail small{display:block;color:var(--muted);margin-top:18px}.pagination{display:flex;align-items:center;justify-content:space-between;margin-top:30px;gap:15px}.prose{max-width:800px}.prose h1{font-size:40px;letter-spacing:-1px}.prose h2{font-size:22px;margin-top:32px}.prose p,.prose li{color:var(--muted)}footer{border-top:1px solid var(--line);padding:30px 32px;color:var(--muted);font-size:12px}.footer-inner{max-width:1176px;margin:auto;display:flex;justify-content:space-between;gap:20px}.footer-links{display:flex;gap:20px}.skip{position:absolute;top:-80px;left:20px;background:#7c6bea;color:white;padding:10px 20px;z-index:10}.skip:focus{top:10px}.line{height:1px;background:var(--line);margin:45px 0}::selection{background:#7d6bd1;color:white}
@media(min-width:1300px){.grid{grid-template-columns:repeat(4,minmax(0,1fr))}.preview{height:220px}}
@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.detail{grid-template-columns:1fr}.detail .preview{height:360px}.hero{padding-top:10px}.hero h1{letter-spacing:-1.5px}.filters{flex-wrap:wrap}.field{min-width:180px}.nav-links{gap:16px}nav{gap:20px}}
@media(max-width:540px){main{padding:30px 20px 50px}nav{padding:16px 20px;min-height:74px}.brand{font-size:16px;letter-spacing:2px}.nav-links a:not(.button){display:none}.nav-links .button{font-size:12px;padding:9px 12px}.grid{grid-template-columns:1fr}.preview{height:270px}.hero h1{font-size:43px}.hero p{font-size:16px}.section-title{align-items:flex-start;flex-direction:column;gap:5px}.filters{padding:14px}.filters .button{width:100%}.detail .preview{height:300px}.detail h1{font-size:30px}.footer-inner{flex-direction:column}.footer-links{flex-wrap:wrap}}
''';

